Invoke-Case 'PROCESS_FACTORY_EVIDENCE_IS_UNTRUSTED' { $p=New-FakeProcess;$r=Invoke-SumiGuardManagedProcessEvidenceConnection -CorrelationId $id -ConfigurationOverride $c -VerificationOverride $v -RunProcess -UseRealProcessAdapter -ProcessFactoryOverride {return $p};$r.process_confirmation_status -ceq 'PROCESS_UNVERIFIED' -and $r.process_confirmation_reason_code -ceq 'PROCESS_EVIDENCE_UNTRUSTED' }
Invoke-Case 'PROCESS_ADAPTER_OVERRIDE_EVIDENCE_IS_UNTRUSTED' { $r=Invoke-SumiGuardManagedProcessEvidenceConnection -CorrelationId $id -ConfigurationOverride $c -VerificationOverride $v -RunProcess -UseRealProcessAdapter -ProcessAdapterOverride {param($plan,$i) if(-not $plan.arguments_verified){return $null};Evidence -ExecutionId $i};$r.process_confirmation_status -ceq 'PROCESS_UNVERIFIED' -and $r.process_confirmation_reason_code -ceq 'PROCESS_EVIDENCE_UNTRUSTED' }
Invoke-Case 'INVALID_UTC_START_TIME_FAILS_CLOSED' { $e=Evidence;$e.observed_start_time_utc='2026-10-30T00:00:00.0000000+00:00';$m=Get-Module SumiGuard.ManagedAssessmentVerification;& $m {param($Evidence) Register-SumiGuardTrustedPostExecutionEvidence -Evidence $Evidence} $e;$r=Test-SumiGuardManagedAssessmentEvidence "Write-Output 'PROCESS_EVIDENCE_OK'" "Write-Output 'PROCESS_EVIDENCE_OK'" $id $id ([pscustomobject]@{fixed_executable_path=$path;observed_executable_path=$path;expected_interpreter_version='5.1.1.1';observed_interpreter_version='5.1.1.1';expected_file_version='5.1.1.1';observed_file_version='5.1.1.1';launch_configuration_verified=$true}) $e;$r.process_confirmation_status -ceq 'PROCESS_UNVERIFIED' -and $r.process_confirmation_reason_code -ceq 'PROCESS_IDENTITY_EVIDENCE_MISSING' }
Invoke-Case 'MODULE_SCOPE_CAN_REACH_REGISTRATION' { $m=Import-Module (Join-Path $root 'src\SumiGuard.ManagedAssessmentVerification\SumiGuard.ManagedAssessmentVerification.psd1') -Force -PassThru;$command=& $m { Get-Command Register-SumiGuardTrustedPostExecutionEvidence -ErrorAction SilentlyContinue };$null -ne $command }

$duplicate=@($executed|Group-Object|Where-Object{$_.Count -ne 1}|ForEach-Object{$_.Name})
$unexecuted=@($planned|Where-Object{$_ -notin $executed})
$unexpected=@($executed|Where-Object{$_ -notin $planned})
$failed=@($results|Where-Object{-not $_.pass}).Count
[pscustomobject]@{success=($failed -eq 0 -and $duplicate.Count -eq 0 -and $unexecuted.Count -eq 0 -and $unexpected.Count -eq 0);test_count=$results.Count;passed_count=$results.Count-$failed;failed_count=$failed;planned_cases=$planned;executed_cases=@($executed);unexecuted_cases=$unexecuted;duplicate_cases=$duplicate;unexpected_cases=$unexpected;child_process_started=0;fixed_command_started=0;child_codex_started=0;network_access_performed=$false;results=@($results)}|ConvertTo-Json -Compress -Depth 5
if($failed -or $duplicate.Count -or $unexecuted.Count -or $unexpected.Count){exit 1}
